;Wild Player plugin;(C) KOSHI/MGN 2026;-------------------------------------------;;source for wild commander ASM compiler v1.0;;-------------------------------------------;HEADER  EQU #0000MAINCOD EQU #0200COD1PG  EQU 0; Main code pageCOD2PG  EQU 3; Resident code pagePL1PG   EQU 1; Players1 pagePL2PG   EQU 2; Players2 pageCOD1LN  EQU 16; Main cod lengthPL1LN   EQU 32; Players1 lengthPL2LN   EQU 9;  Players2 lengthCOD2LN  EQU ENDCOD2-STARTCOD2; Resident code lengthPLAYER1 EQU MAINCOD+COD1LN*512PLAYER2 EQU PLAYER1+PL1LN*512COD2    EQU PLAYER2+PL2LN*512NZ0CHAR EQU 9+11;     Noize LowNZHCHAR EQU NZ0CHAR+5;Noize Hi;-------RESIDENT_JP   EQU #6020; Plugin SystemRESIDENT_CALL EQU #6028; Plugin System;-------Frames  EQU 49;        Frames per secTimeOut EQU Frames*10; 10 Secs wait MAXF10flg  EQU 3        ORG HEADER;-------WLD     EQU #6006; Plugin System Call PointTMN     EQU #6009; TimerHEI     EQU #600E; Height (25,30,36)FUX     EQU #6026PLHDRS  EQU 5; Play List Headers;-------        DS 16        DB "WildCommanderMDL";    Header        DB #11;                  Version        DB 0        DB 4; Pages to store        DB 0; Page to #8000 at Start        DB COD1PG,COD1LN;      MAIN code        DB PL1PG,PL1LN;       PLAYERS1        DB PL2PG,PL2LN;       PLAYERS2        DB COD2PG,COD2LN/512+1;RESIDENT.2      DB 0,0        DS 16        DB "C  ";0        DB "M  "        DB "MUZ"        DB "$M "        DB "$P "        DB "ASC";5        DB "SQT"        DB "STC"        DB "FLS"        DB "STP"        DB "FTC"        DB "PSC"        DB "PT1";12        DB "PT2"        DB "PT3"        DB "GTR"        DB "TFC"        DB "VTX"        DB "VT "        DB "FXM"        DB "SAA"        DB "PSM";21        DB "ETC";22        DB "P_M";23        DB "P_C"        DB "P_S"        DB "P_A"        DB "P_P"        DB "P_F"        DB "TFD";29        DB "AYL";30        DB "M3U";31        DB 0;    end token        DW #0000,#000F;                        Max File Size        DB "Wild Player Plug-in v1.84       "; Plugin Name        DB 5;                                  Type (SHIFT+F3;F10 menu;by EXT)        DS 6        DB "Play by Wild Player     ";         Green menu        DS 32;WC.INI options:PAR1    DB PAR2-PAR1;Structure size        DB 1;Default option        DB "repeat"        DB 2;Options count        DB "all",0        DB "one",0PAR2    DB PAR3-PAR2        DB 3;Default option        DB "mode"        DB 3;Options count        DB "forward",0        DB "backward",0        DB "shuffle",0PAR3    DB PAR3END-PAR3        DB 1;Default option        DB "stop"        DB 2;Options count        DB "no",0        DB "yes",0PAR3END NOP;END TOKEN;---------------------------------------        ORG #8000,MAINCOD;-------;Text screen modes:HEIMIN  EQU 25HEIMID  EQU 30HEIMAX  EQU 36;Main WindowMDXzero EQU 19;       X without PlayList (txt mode 80)MDXZ36  EQU 24;       X without PL (txt mode 90)MDX     EQU 4;        X mode 80MDX36   EQU 9;        X mode 90MDY     EQU 5;        Y mode 30MDY25   EQU 3;        Y mode 25MDY36   EQU 8;        Y mode 36MDW     EQU 42;       widthMDH     EQU 15;       height;Analyzer WindowANX     EQU MDXANX36   EQU MDX36ANY     EQU MDY+MDH-1ANY25   EQU MDY25+MDH-1ANY36   EQU MDY36+MDH-1ANW     EQU MDWANH     EQU 4;PlayList WindowPLX     EQU MDX+MDWPLX36   EQU MDX36+MDWPLY     EQU MDYPLY25   EQU MDY25PLY36   EQU MDY36PLW     EQU 30PLH     EQU MDH+ANH-1;Help WindowHLPX    EQU 255HLPX25  EQU 255HLPX36  EQU 255HLPY    EQU ANY+ANH+1HLPY25  EQU ANY25+ANHHLPY36  EQU ANY36+ANH+1HLPW    EQU 62HLPH    EQU 6HLPC    EQU %01001111;Warning WindowERRW    EQU 40ERRH    EQU 2+2ERRC    EQU %10101111;Loading WindowLOADW   EQU 40LOADH   EQU 1+2LOADC   EQU %01101111CURclrP EQU MDC-1CURclr  EQU %01011000CURmsk  EQU %00000111MDC     EQU %01111111;-------INSTM   EQU #C000PLAYM   EQU #C005STOPM   EQU #C008TFDPLAY EQU #C003;TFD PLAY pointTFDCUR  EQU #C009;TFD PLAY offset (PLAYER)EOM     EQU #C00D;TFD EndOfMusic flag (PLAYER)TFDFLG  EQU 3TFDPATCH  EQU INSTM+#32;OUT (#FE) -> NOP:NOPTFDPATCH2 EQU INSTM+#39;OUT (#FE) -> NOP:NOP;-------PT3PL   EQU #0BE1PT2PL   EQU #0A0CFMPL    EQU #0743VTPL    EQU #086E;-------SECBU   EQU #9E00LOBU    EQU #A000;---------------------------------------WP333   LD (DAIX),IX,E,1        LD (SSTAT),A:CP F10flg:CALL Z,LOADtest        EXA:LD (EXTNUM),A;    file EXT number (0-31)        LD (DADE),HL;         file size [DE,HL]        LD (FILEINF+1),BC;    file name string        XOR A:LD (WINDZ+1),A; window printed flag         LD A,E,(ESTAT),A;     exit state flag (1 - unknown file)        CALL INITZ;        inits (RNDseed, loadINIoptions)        LD A,(EXTNUM):CP 30:JR C,NOPL; 30=AYL, 31=M3U;AYL/M3U:        XOR A        LD (ESTAT),A        CALL EXGENPL        CALL GEDPL        CALL ONLY1TRACK:JP Z,ENTRnPL;If 1 track in PL -> play it in standard mode;play list mode:PLSTART CALL NEED        LD HL,(PLGE),BC,0-#C000:ADD HL,BC.2      SRL H:RR L        LD (PLcount),HL        JP ENTR;load firs music in PL, then going to main cycle;-------YEMR    ;Marked Files -> Play List        CALL MGENPL        LD HL,(FILEINF+1),(HL),0        JR PLSTART;not AYL/m3u:NOPL    LD HL,0:CALL TMRKDFL:JR NZ,YEMR;no marked files:NOMR    ;CALL UGENPL        LD A,1,(PLMD),A; Play List mode off;-------NEW     CALL NP6,NP06        CALL GEDPL        LD A,(SSTAT):CP F10flg:JR NZ,NORMIS:CALL LOADtst:JR SIMRONNORMIS  LD B,16+32,HL,LOBU:CALL LOAD512        LD B,32:CALL LOAD512SIMRON  LD A,(DETKA):OR A:CALL NZ,TFMDET        CALL ZAPUMZ        CALL NEED        LD A,(MUZPL):OR A:JR NZ,MAIN        CALL LMD,Z,WARNING:JR NZ,EXI4        LD A,(Mloop):OR A:JP Z,NXTMZ;if music not started go to next (ALL)        LD A,(Mstop):OR A:JP Z,NXTMZ;ONE+PLAY;ONE+STOPMAIN    EI:HALT:CALL ATIT        CALL PMACH:JP NZ,NXTMZ        CALL CLOCK:LD HL,ANALYZEanpr,A,(TSMZ),BC,(FMMZ):CALL COD2RES        CALL LMD,Z,PLSHOW        LD IX,PLWND        CALL LMD:JR NZ,WOPL        CALL CURSOR,PBNOW        CALL UPPP,NZ,CRUP        CALL DWWW,NZ,CRDNWOPL    CALL F1KE,NZ,HLPSHOW        CALL F2KE,NZ,MODLOOP        CALL F3KE,NZ,MODSTEP        CALL F4KE,NZ,MODSTOP        CALL ENKE:JP NZ,ENTR        CALL SPKE:JR NZ,NXTMZ        LD A,1:CALL KBSCN        CP "m":CALL Z,PAUSE_MUSIC        CALL ESC:JR Z,MAINEXI4    XOR A:LD (ESTAT),AEXI3    EI:HALT        CALL DEFNT        LD HL,HLPWNDrresb:CALL HMD,NZ,COD2RES        LD IX,PLWND:CALL LMD,Z,RRESB        LD HL,ANWNDrresb:CALL COD2RES        CALL AYOFF        LD IX,MNWND:CALL RRESB        LD A,(ESTAT):CP 2:RET C        CALL LMD:LD A,2:RET NZ        XOR A        RET;-------PAUSE_MUSIC LD A,1,HL,PAUS:XOR (HL):LD (HL),A:JP AYOFF;-------LMD     LD A,(PLMD):OR A:RETHMD     LD A,(HPMD):OR A:RET;-------NXTMZ   LD A,(Mstop),C,A        LD A,(Mloop):DEC A:JR NZ,ALLmd:DEC C:JP Z,STOP,ENTR;ONEALLmd   CALL LMD:JR NZ,ENTR        LD IX,PLWND        LD A,(Mstep)        DEC A:JR Z,BCKWARD;BCKWARD        DEC A:JR Z,SHUFFLE;SHUFFLE        JR FORWARDSHUFFLE LD BC,(PLcount):DEC BC:LD A,B:OR C:INC BC:JR Z,ONEpi        LD HL,RND_GENres:CALL COD2RES        LD HL,BC,DE,(PLAYcur):OR A:SBC HL,DE:JR Z,SHUFFLEONEpi   LD HL,BC:CALL PLGO        JR ENTRBCKWARD CALL PlayCRUP:JR WARDFORWARD CALL PlayCRDNWARD    JR NC,ENTR        LD A,(Mstop):DEC A:JR Z,STOP;Forward repeat ALL        CALL PLINT        LD A,(Mstep):OR A:JR Z,ORDER1;FORWARD        LD HL,(PLcount):DEC HL:CALL PLGOORDER1  LD A,(MUZPL):OR A:JP Z,MAIN        JR ENTRENTRnPL LD A,1,(PLMD),A:CALL NEED:JR ENTRnpl;PL with 1 track -> no PLENTR    CALL AYOFF        CALL LMD:JP NZ,EXI3;Next File if not in PL modeENTRnpl CALL GWZ:JP C,EXI3        LD (PLAYcur),DE,(IX+24),1;Playing cursor        LD DE,SECBU        PUSH DE:XOR A:LD (DE),A:INC DE        LD BC,#FF0E:CALL Ldr        XOR A:LD (DE),A       LD HL,LOADINGprwow:CALL COD2RES        POP HL        CALL FENTRY:LD (DADE),HL       PUSH AF:LD HL,LOADINGrresb:CALL COD2RES       POP AF:JP Z,EXI3;LD A,D:OR E:JR NZ,EXI3;LD (DADE),HL        CALL GFILE        JP NEWSTOP    LD HL,#0100,(MUZPL),HL:CALL AYOFF:JP MAIN;-------CRUP    LD IX,PLWND        LD A,(IX+12):CP 1:JR Z,SRLUP:DEC (IX+12)        JR RFRHSRLUP   LD L,(IX+22),H,(IX+23)        LD A,L:OR H:JR Z,EDGE        DEC HLGLOB    LD (IX+22),L,(IX+23),H        JR RFRHCRDN    LD IX,PLWND        LD A,(IX+12):CP (IX+13):JR NC,SRLDN:INC (IX+12)RFRH    LD (IX+24),1        XOR A        RETSRLDN   INC (IX+12):CALL GWZ        DEC (IX+12):RET C        LD L,(IX+22),H,(IX+23):INC HL        JR GLOBEDGE    SCF        RET;-------PlayCRUP CALL PlayEcur:JR Z,CRUP         EX DE,HL:DEC HL         CALL PLGO:JR NC,EDGE         XOR A         RETPlayCRDN CALL PlayEcur:JR Z,CRDN         EX DE,HL:INC HL         CALL PLGO:JR NC,EDGE         XOR A         RETPlayEcur LD (IX+24),1         LD DE,(PLAYcur)         LD L,(IX+22)         LD H,(IX+23)         LD B,0         LD C,(IX+12):DEC C         ADD HL,BC         OR A:SBC HL,DE         RET;---------------------------------------MODLOOP LD HL,Mloop,DE,MLOOP:JP TTTMODSTEP LD HL,Mstep,DE,MSTEP:JP TTTMODSTOP LD HL,Mstop,DE,MSTOP:JP TTT;-------PBNOW   LD DE,(PLcount),B,0:CALL PB_PL        LD L,(IX+22)        LD H,(IX+23),B,1:JP PB_PL;---------------------------------------;Reset play modes, init , one time initsINITZ   LD A,0:OR A:CALL Z,FIRST_S        XOR A        LD (PLMD),A        LD (HPMD),A        LD (ANFNT+1),A        LD C,0;just init (update field)        LD HL,Mloop,DE,MLOOP:CALL T_T        LD HL,Mstep,DE,MSTEP:CALL T_T        LD HL,Mstop,DE,MSTOP:JP T_T;-------FIRST_S INC A:LD (INITZ+1),A:CALL DECODEx;Fast access to WC API (direct call's)        LD A,1:CALL PRM_PL,NZ,oREPEAT;load options from wc.ini        LD A,2:CALL PRM_PL,NZ,oMODE        LD A,3:CALL PRM_PL,NZ,oSTOP        LD HL,RND_INIres:CALL COD2RES;RND seed init        REToREPEAT DEC A:LD (Mloop),A:REToMODE   DEC A:LD (Mstep),A:REToSTOP   DEC A:LD (Mstop),A:RET;-------DECODEx LD HL,(FUX)        LD DE,3*2:ADD HL,DE        LD E,(HL):INC HL        LD D,(HL):INC HL:LD (PRSRWx+1),DE        LD E,(HL):INC HL        LD D,(HL):INC HL:LD (PRIATx+1),DE        RET;---------------------------------------LOADtest LD HL,TESTend-TESTcod;size         LD BC,TESTnm;name         XOR A:LD E,A:EXA         RETLOADtst  LD HL,LOAD_TSTres:CALL COD2RES:LDIR         RET;---------------------------------------WARNING CALL PLSHOW        LD HL,WARNINGres,BC,(STA):CALL COD2RES        DEC B        RET;---------------------------------------HLPSHOW CALL HMD:JR Z,HLPshow        XOR A:LD (HPMD),A,HL,HLPWNDrresb:JP COD2RESHLPshow LD A,1,(HPMD),A,HL,HLPWNDprwow,DE,(HLPWNDxy):JP COD2RES;---------------------------------------PLGO    ;Play List position INIT;        i:IX - PLWND;          HL - position;        o:NC - error;           C - curpoz(IX+12),globY(IX+22/23),PLprintFLG(IX+24) init        LD BC,HL        LD DE,(PLcount):OR A:SBC HL,DE:RET NC;out of PL;stay in same window position, if it possible (globY+curMAX>=HL>=globY):        LD L,(IX+22)        LD H,(IX+23)        LD DE,BC        EX DE,HL:OR A:SBC HL,DE        EX DE,HL        LD A,D:OR A:JR NZ,STAYnot        LD A,E:CP (IX+13):INC A:JR C,STAYpozSTAYnot LD HL,(PLcount),D,0,E,(IX+5):DEC E:OR A:SBC HL,DE:JR C,SHORTpz        SRL E:LD HL,BC:OR A:SBC HL,DE:JR C,MIDpoz        LD BC,HL,A,E:JR LONGpozMIDpoz  XOR A:SUB L:LD C,ASHORTpz LD A,C,BC,0LONGpoz INC A        LD (IX+22),C        LD (IX+23),BSTAYpoz LD (IX+12),A,(IX+24),1        SCF        RET;-------PLSHOW  ;Print/refresh PL window        LD IX,PLWND,A,(IX+24):OR A:RET Z;PL refresh needed?        DEC (IX+24)        LD HL,#0101,(PLHL),HL;XY INIT        XOR A:LD (LDR+1),A;PLend flag INIT        LD L,(IX+22),H,(IX+23);globY        LD B,(IX+5):DEC B:LD (IX+13),B;windowH-1=curMAX=rowCountLSH     PUSH HL,BC:CALL PRLIN        POP BC,HL:INC HL:DJNZ LSH        RET;-------PRLIN   ;Print Line;        i:    HL - globY;          (PLHL) - XY;        o:(PLHL) - Next row (Y=Y+1)        PUSH HL:LD DE,(PLAYcur):OR A:SBC HL,DE        POP HL        PUSH AF        CALL GWE        CALL LDR:JR NC,LuR        LD A," ",(DE),A:INC E:DJNZ $-2;Clear rest of line if neededLuR     LD BC,PLW-2        LD HL,(PLHL),DE,HL        INC H:LD (PLHL),HL        LD HL,SECBU:CALL PRSRWx;HL - Text; DE - XY; BC - Length        POP AF:JR Z,$+6:LD A,MDC:JR $+4:LD A,CURclrP        JP PRIATx;-------;Copy File Name to SECBULDR     LD A,0;PLend flag        LD C,B        LD B,PLW-2,DE,SECBU:OR A:SCF:RET NZ;is PL ended?        LD B,A:ADD HL,BC        LD BC,#5C+(128)*256;"/"+128b(max length)        CALL MJ20X:INC HL;goto name start (without path)        LD DE,SECBU,BC,14+(PLW-2)*256MYJ     LD A,(HL):CP C:RET C:LD (DE),A:INC HL,E:DJNZ MYJ        XOR A        RET;-------Ldr     ;Copy Path to LOBU (512b MAX).2      LD A,(HL):CP C:RET C:LD (DE),A:INC HL,DE        DJNZ Ldr        XOR A        RET;-------MJ20X   LD A,H:CP #C0:JR Z,MJ20xMJ20    DEC HL:LD A,(HL)        CP C:RET Z        CP #D+1:RET C        DJNZ MJ20        RETMJ20x   LD A,L:DEC HL:OR A:RET Z        LD A,(HL)        CP C:RET Z        CP #D+1:RET C        DJNZ MJ20x        RET      ;-------GWE     ;i:HL - globY;        o:notEoPL: CHL - page+address;                     B - length;             EoPL: set (LDR+1) - ENDofPlayList and (IX+13) - curMAX        LD A,(LDR+1):OR A:RET NZ;is PL ended?        PUSH HL:CALL NPG        POP HL        LD DE,#C000.2      ADD HL,HL        ADD HL,DE        LD C,(HL):INC L        LD E,(HL):INC L        LD D,(HL):INC L        LD B,(HL):EX DE,HL        LD A,H:CP #C0:JR NC,GWe        LD A,1,(LDR+1),A        LD A,(PLHL+1):DEC A        LD (IX+13),A;curMAX        RETGWe     LD A,C,(PLPG),A:JP NPX;-------GWZ     ;i:none;        o: C - error (out of PL);           Z - HL - address in page #C000-#FFFF (PLPG);               DE - track number        LD IX,PLWND        CALL NPG        LD L,(IX+22),H,(IX+23)        LD D,0,E,(IX+12):DEC E        ADD HL,DE:LD (GLOBy+1),HL        LD DE,#C000.2      ADD HL,HL        ADD HL,DE        LD C,(HL):INC L        LD E,(HL):INC L        LD D,(HL):EX DE,HL        LD A,H:CP #C0:RET C        LD A,C,(PLPG),A        CALL NPXGLOBy   LD DE,0        XOR A        RET;-------PLINT   XOR A        LD (IX+22),A        LD (IX+23),A        LD (PLAYcur+0),A        LD (PLAYcur+1),A        INC A        LD (IX+12),A        LD (IX+24),A        RET;---------------------------------------MGENPL  CALL PLINI        LD HL,0,(X+1),HL:CALL X        JR PLENDX       LD HL,0        INC HL:LD A,H:CP 8:RET NC        LD (X+1),HL:SET 7,H        LD DE,SECBU:CALL TMRKDFL:RET NZ        LD HL,SECBU:CALL GENLN        JR X;-------PLINI   XOR A        LD (PLPG),A        LD HL,#C000        LD (PLGE),HL        LD (PLHL),HL        RETPLEND   CALL NPG        XOR A        LD HL,(PLGE).3      LD (HL),A:INC HL        RET;-------GENLN   LD A,(PLPG):CALL NPX        LD DE,(PLHL)        LD BC,#FF0EDLN.2      LD A,(HL):CP C:JR C,SNDL:LD (DE),A:INC HL,DE        DJNZ DLN;error!SNDL    LD A,#D,(DE),A        PUSH HL,DE        LD HL,(PLHL):EX DE,HL:OR A:SBC HL,DE:LD A,L,(PLED),A        CALL NPG:LD DE,(PLGE),HL,PLPG,BC,4:LDIR:LD (PLGE),DE        POP DE,HL:INC DE        LD A,D:CP #FE        LD A,(PLPG):JR C,NDL        LD DE,#C000:INC ANDL     LD (PLPG),A        LD (PLHL),DE        RET;-------PLPG    NOP ;- ! page and offsetPLHL    DS 2;/PLED    NOP;/PLGE    DS 2;offset in PL headers;---------------------------------------ONLY1TRACK LD HL,(PLGE),DE,#C000:OR A:SBC HL,DE:LD A,H:OR A:RET NZ:LD A,L:CP 4:RET;-------EXGENPL CALL PLINI        LD HL,LOBU,B,8:CALL LOAD512        LD HL,LOBU,DE,AYLH;check for AYL header        CALL SRHMZ:LD DE,LOBU:JR NZ,M3;nope        LD B,0:CALL MJ35;Skip Full Header (AYL)        LD A,(HL):CP 10:JR NZ,$+3:INC HL        EX DE,HLM3      EX DE,HL:CALL CABOOM        JP PLENDCABOOM  XOR A:LD (LOBU-1),A        LD DE,(PLGE)OEE     LD A,H:CP LOBU[+#08:JR NC,TLOee     LD A,(HL)        CP "<":JR Z,TWKL;AYL metadata skips        CP "#":JR Z,TWKLMOEe     CALL MJ30:JR NC,NEE        LD A,(HL)        CP #0A:JR NZ,$+3:INC HL        LD A,(HL):OR A:JR NZ,OEENEE     RET;-------MJ30    CALL GENLN:LD A,(HL):OR A:RET Z:INC HL:SCF:RETMJ35    LD A,(HL):INC HL:CP 14:RET C        DJNZ MJ35        RETTL      LD BC,#0800:OR A:SBC HL,BC        PUSH HL        LD HL,LOBU+#0800        LD DE,LOBU:LDIR        EX DE,HL:LD B,4:CALL LOAD512        POP HL        JR OeeTWKLM   INC HL        LD A,(HL):INC HL        LD B,(HL):DEC HL,HL        CP "E":JR NZ,OEe        LD A,B:CP "X":JR NZ,OEe        JR TWKTWKL    LD B,0:CALL MJ35        LD A,(HL)        OR A:JP Z,NEE        CP #0A:JR NZ,$+3:INC HL        LD A,(HL)        CP ">":JR NZ,TWKLTWK     LD B,0:CALL MJ35        LD A,(HL)        CP #0A:JR NZ,$+3:INC HL        LD A,(HL):OR A:JR Z,NEE        JP Oee;---------------------------------------TTT     LD C,1;Change to next and updateT_T     LD A,(HL):ADD A,C        PUSH HL:INC HL        LD C,(HL):INC HL        LD B,(HL):INC HL:CP B:JR C,$+3:XOR A        LD B,0        PUSH AF        OR A:JR Z,UUU:ADD HL,BC:DEC A:JR NZ,$-2UUU     LDIR        POP AF        POP HL        LD (HL),A        RET;---------------------------------------NEED    LD HL,0        LD (P_SH),HL,(TME),HL,(P_NU),HL        CALL WINDZ,MNINF,ANFNT        CALL PLRINF,PRINFO        CALL PBCLC        JP PBFCLR;---------------------------------------WINDZ   LD A,0:OR A:RET NZ        INC A:LD (WINDZ+1),A        LD A,(HEI)        LD HL,MODE25,DE,6        CP HEIMIN:JR Z,STLOAD        LD HL,MODE30 