YCAYFXM   LD DE,FXDL        CALL GETMZ        LD HL,#C000+2,BC,FXLN        CALL GETPL2        JP LUZZTRYC    LD HL,LOBU;                  PT1        LD A,(HL):CP 24:JR NC,TRYD.3      INC HL        LD A,(HL):INC HL        OR (HL):JR NZ,TRYD        LD HL,LOBU+69,B,30-1BHG     LD A,(HL):INC HL        CP #20:JR C,TRYD        DJNZ BHGAYPT1   LD DE,PT1DL        CALL GETMZ        LD HL,#C000+4,BC,PT1LN        CALL GETPL2        LD HL,PT1DL+69,DE,GTPR,C,30:LDIR        JP LUZZTRYD    CALL NP6;                    SQT        CALL SQTIDEN:JP NZ,NEmUZ        LD HL,(DADE)        LD DE,(LOBU),(DAR+1),DE        SBC HL,DE:JR C,NTS        LD A,H:CP 3AYSQT   JR C,NTS        CALL NP8        LD HL,LOBU,DE,#E000,BC,#2000        PUSH HL,DE,BC        LDIR        CALL GSQT,NP8        POP BC,HL,DE        LDIR        CALL NP6DAR     LD HL,0,DE,LOBU        ADD HL,DE        LD BC,#4000-SQLN        LDIR        CALL SQTIDEN:JR NZ,NTS+3        LD HL,LOBU        EXX:LD DE,SQDL:EXX        CALL ASS        LD HL,NP8,(LAG+1),HL        LD HL,#C000+18,BC,SQLN        CALL GETPL        LD HL,NP1,(LAG+1),HL        CALL INSTM        LD A,1,(TSMZ),A,(TSFG),A        LD HL,#C064,(CTOL2+1),HL        JR NTS+3NTS     CALL GSQT,NP1        LD A,#64        JP LUZZ+2GSQT    LD DE,SQDL        CALL GETMZ        LD HL,#C000+18,BC,SQLN        JP GETPLSRHMZ   LD A,(DE):OR A:RET Z        CP (HL):RET NZ        INC HL,DE        JR SRHMZGETPL2  CALL NPe:JR $+2+3GETPL   CALL STN        LD A,(HL):INC HL        LD H,(HL),L,A        LD DE,LOBU        PUSH DE,BC        DI        CALL #C000;!        EILAG     CALL NP1        POP BC,HL        LD DE,#C000        LDIR        RETGETMZ   PUSH DE:CALL NP1        POP DE        LD HL,LOBU,BC,#2000:LDIR        LD (DAHL),DE        CALL NP6        LD HL,#C000,DE,LOBU,BC,#2000:LDIR        CALL NP1,NP062        LD DE,(DAHL),HL,LOBU,BC,#2000:LDIR        PUSH DE:CALL NP6        POP DE: LD HL,#E000,BC,#2000:LDIR        CALL NP1,NP062        RET;---------------------------------------NOSQT   LD A,1:OR A        RET;IDENTIFSQTIDEN LD IX,LOBU        LD A,(IX+#00):CP #3E:JR NZ,NOPLR        LD A,(IX+#02):CP #32:JR NZ,NOPLR        LD A,(IX+#05):CP #32:JR NZ,NOPLR        LD A,(IX+#08):CP #32:JR NZ,NOPLR        LD A,(IX+#0B):CP #01:JR NZ,NOPLR        LD HL,LOBU+SQLN        LD DE,LOBU        LD BC,#4000-SQLN        LDIRNOPLR   LD DE,(LOBU)        LD A,D:CP #40:JR NC,NOSQT        OR E:JR Z,NOSQT        LD HL,LOBU-1:ADD HL,DE        LD A,(HL):CP 9:JR NC,NOSQT        DEC HL        LD B,6SQ1     LD A,(HL):OR A:JR NZ,NOSQT        DEC HL        DJNZ SQ1        LD A,(HL)        OR A:JR Z,NOSQT        CP #21:JR NC,NOSQT        XOR A        RET;---------------------------------------ANFNT   LD A,0:OR A:RET NZ        INC A:LD (ANFNT+1),A                LD HL,FNTDECHCOD2RES EXA:LD A,COD2PG:JP RESIDENT_CALLDEFNT   LD A,#FF:CALL MNGC_PL        LD HL,#C800,DE,#C000,BC,8*20        LDIR        RET;-------ATIT    LD A,(TSFG):OR A:JR NZ,NEPL        LD BC,(MUZPL)        LD A,(GXMO):OR C:JR Z,NEPL        LD A,C:OR A:JR Z,NEPL        LD A,B:OR A:JR NZ,NEPL        LD HL,(TME):INC HL:LD (TME),HL        LD HL,(TMM):INC HL:LD (TMM),HL        LD C,0:CALL TURBO        CALL NP1,NP062CTOL    CALL PLAYM        LD A,(TSMZ):OR A:JR Z,NEPL        CP 1:JR NZ,NEPL        CALL NP8,NP06        LD BC,#FFFD,A,#FE:OUT ACTOL2   CALL PLAYM        LD BC,#FFFD,A,#FF:OUT ANEPL    LD C,2:JP TURBO;-------CLOCK   LD HL,(TMM),DE,CLOK        LD BC,49*60,A,255        OR A:INC A:SBC HL,BC:JP NC,$-3        LD (DE),A:INC DE        ADD HL,BC        LD BC,49,A,255        OR A:INC A:SBC HL,BC:JP NC,$-3        LD (DE),A:INC DE        ADD HL,BC        LD A,L:ADD A,A        LD (DE),A        LD DE,SPR,A,(CLOK+0):CALL DEC0,PRDIS        LD DE,SPR+10,A,(CLOK+1):CALL DEC0,PRDIS        LD DE,SPR+20,A,(CLOK+2):CALL DEC0,PRDIS        LD IX,MNWND        LD HL,SPR+#00,DE,#0103,BC,27:CALL PRSRWx        LD HL,SPR+#20,DE,#0203,BC,27:CALL PRSRWx        LD HL,SPR+#40,DE,#0303,BC,27:CALL PRSRWx        LD HL,SLINE,DE,#0401,BC,40:CALL PRSRWx        LD HL,MODES,DE,#011F,A,(PLMD):DEC A:CALL NZ,TXTPR        LD HL,SN1,A,(PBSTP+1):CALL NORK        LD HL,SN2,A,(P_NU):CALL NORK                LD HL,TXTSN1,DE,#0500:JP TXTPRDEC0    LD C,#FF        INC C:SUB 10:JR NC,$-3        ADD A,10        RET;-------;Print DigitsPRDIS   ;i: DE - Dest Address;            C - Digit1;            A - Digit2          PUSH AF,DE        CALL GDF        POP DE,BC        LD C,B.4      INC DEGDF     LD H,0,L,C        PUSH HL.3      ADD HL,HL        POP BC        ADD HL,BC;*9        LD BC,DIGITS:ADD HL,BC        LD A,3DDF.3      LDI        EX DE,HL:LD BC,32-3:ADD HL,BC        EX DE,HL        DEC A:JR NZ,DDF        RET;---------------------------------------PBLNE   LD A,(NOWT+1)        CP 2:JR Z,PBVT        CP 4:JR C,PBFCLRPBVT    LD A,(P_NU):DEC A:CALL Z,PBCLR        INC A        LD H,0,L,A.4      ADD HL,HL        PUSH HL;*16        ADD HL,HL        PUSH HL;*32.3      ADD HL,HL;               *256.2      POP BC:ADD HL,BCPBSTP   LD DE,0        LD A,D:OR E:JR Z,PBCLR        LD BC,0-1        OR A:INC BC:SBC HL,DE:JP NC,$-3        LD HL,304        OR A:SBC HL,BC        JR NC,$+5:LD BC,304        LD HL,PBLINE        LD A,C.3      SRL B:RR C        JR Z,PBL        LD B,CFLPB    LD (HL),19:INC HL:DJNZ FLPBPBL     AND 7:RET Z        LD DE,PBTBL-1        LD B,A:INC DE:DJNZ $-1        LD A,(DE),(HL),A        RETPBFCLR  LD HL,PBLINE        PUSH AF        LD B,38,A,11CFPB    LD (HL),A:INC HL:DJNZ CFPB        POP AF        RETPBCLR   LD HL,PBLINE        LD B,38CLPB    LD (HL),11:INC HL:DJNZ CLPB        RETPBTBL   DB 12,13,14,15,16,17,18PBCLC   CALL NP1        LD A,(NOWT+1)        ;CP 17:JR Z,PSMPB        CP 15:JP Z,ET        CP 14:JP Z,PT1        CP 13:JP Z,PB11 