062   LD A,4:EXA:LD A,80:JP WLD;BUFFER3 (#0000)NP1     LD A,1:EXA:LD A,65:JP WLD;MDL1 (#C000)NP8     LD A,2:EXA:LD A,65:JP WLD;MDL2 (#C000)NPG     LD A,PLHDRS:EXA:LD A,65:JP WLD;PLHDRSNPX     PUSH HL,DE,BC        ADD A,PLHDRS+1:EXA:LD A,65:CALL WLD        POP BC,DE,HL        RET;-------WAIT    PUSH BC:LD B,0:DJNZ $        POP BC        RETTFMDET  XOR A:LD (DETKA),A        LD BC,#FFFD,A,%11111000:OUT A:CALL WAIT        XOR A:OUT A:CALL WAIT        LD B,#BF:OUT B:CALL WAIT        LD B,#FF:INF:LD A,1:JP P,FM_EN        XOR AFM_EN   LD (TSFM),A;-------SAAON   CALL SAAOFF        LD BC,#FFFD,A,#F6:OUT A        RETSAAOFF  LD BC,#00FF        XOR A:LD E,ABAROQUE INC B:OUT A        DEC B:OUT E        INC A:CP 32:JR C,BAROQUE        RETAYOFF   CALL SAAOFF        LD BC,#FFFD,A,#FE:OUT A        PUSH BC:CALL AYFF        POP BC        LD A,#FF:OUT AAYFF    XOR A        LD BC,#FFFD,D,8:OUT D        LD E,B        LD B,#BF:OUT A        LD B,E:INC D:OUT D        LD B,#BF:OUT A        LD B,E:INC D:OUT D        LD B,#BF:OUT A;Noize:        LD A,%00111111        LD B,E,D,7:OUT D        LD B,#BF:OUT A        RET;---------------------------------------;Wild Player plugin;---------------------------------------MODE25  DB MDXzero,MDY25,MDXzero,ANY25,HLPX25,HLPY25        DB PLX,PLY25,MDX,MDY25,ANX,ANY25,HLPX25,HLPY25MODE30  DB MDXzero,MDY,MDXzero,ANY,HLPX,HLPY        DB PLX,PLY,MDX,MDY,ANX,ANY,HLPX,HLPYMODE36  DB MDXZ36,MDY36,MDXZ36,ANY36,HLPX36,HLPY36        DB PLX36,PLY36,MDX36,MDY36,ANX36,ANY36,HLPX36,HLPY36;-------MNWND   DB 4+16+128,0        DB MDX,MDY;    X,Y        DB MDW,MDH;    W,H        DB MDC;        PAPER+INK        DB 0        DW #0000;      BUFFER        DB 3,6;        LINES        DW MNTXT        DW 0        DW 0MNTXT   DB #E,#9,"Wild Player Plugin v1.84",0;---------------------------------------PLWND   DB 5+16+128,CURmsk        DB PLX,PLY;    X,Y        DB PLW,PLH;    W,H        DB MDC;        PAPER+INK        DB 0        DW #0000;      BUFFER        DB 0,0;        LINES        DB 1;     +11  curNOW        DB PLH-2; +12  curMAX        DB CURclr;     curCOLOR        DB MDC;        UNDcur        DW PLTXT        DW 0        DW 0        DW 0;+22       GLOBAL Y        DB 0;+24       PRINTflgPLTXT   DB #E        DB #9,"Play List"        DB 0;---------------------------------------PTI     DB #21,#94:DW PLIH;PSM        DB #C3,#0E:DW PLIG;TFD        DB #21,#B3:DW PLIF;SAA        DB #21,#C6:DW PLIE;PT1        DB #21,#E1:DW PLI1;PT3        DB #21,#0C:DW PLI2;PT2        DB #18,#0A:DW PLI4;ASC        DB #21,#3C:DW PLI5;STC        DB #21,#68:DW PLI6;STP        DB #3E,#08:DW PLI7;SQT        DB #21,#AB:DW PLI8;PSC        DB #21,#05:DW PLI9;FTC        DB #21,#6E:DW PLI3;VTX        DB #21,#9A:DW PLIA;GTR        DB #21,#3D:DW PLIB;TFC        DB #21,#E6:DW PLIC;FLS        DB #C3,#09:DW PLID;FXMPTIX    DW PLIXNOWT    DW 0;-------PLI1    DB "Pro Tracker v3.x       ",0PLI2    DB "Pro Tracker 2          ",0PLI3    DB "Vortex Tracker II      ",0PLI4    DB "ASC Sound Master       ",0PLI5    DB "Sound Tracker          ",0PLI6    DB "Sound Tracker Pro      ",0PLI7    DB "SQ Tracker             ",0PLI8    DB "Pro Sound Creator v1.0x",0PLI9    DB "Fast Tracker v1.0x     ",0PLIA    DB "Global Tracker         ",0PLIB    DB "TFM Compiler v1.x      ",0PLIC    DB "FLASH Tracker          ",0PLID    DB "Fuxoft AY Language     ",0PLIE    DB "Pro Tracker 1          ",0PLIF    DB "E-Tracker              ",0PLIG    DB "TFM unpacked           ",0PLIH    DB "Pro Sound Maker        ",0PLIX    DB 32,0;-------DIGITS  DB #DC,#DC,#DC;0        DB #DB,#20,#DB        DB #DB,#DC,#DB        DB #20,#DC,#20;1        DB #DF,#DB,#20        DB #DC,#DB,#DC        DB #DC,#DC,#DC;2        DB #DC,#DC,#DB        DB #DB,#DC,#DC        DB #DC,#DC,#DC;3        DB #20,#DC,#DB        DB #DC,#DC,#DB        DB #DC,#20,#DC;4        DB #DB,#DC,#DB        DB #20,#20,#DB        DB #DC,#DC,#DC;5        DB #DB,#DC,#DC        DB #DC,#DC,#DB        DB #DC,#DC,#DC;6        DB #DB,#DC,#DC        DB #DB,#DC,#DB        DB #DC,#DC,#DC;7        DB #20,#20,#DB        DB #20,#20,#DB        DB #DC,#DC,#DC;8        DB #DB,#DC,#DB        DB #DB,#DC,#DB        DB #DC,#DC,#DC;9        DB #DB,#DC,#DB        DB #DC,#DC,#DB;-------PTFO    DB "ProTracker 3.",0VORT    DB "Vortex Tracker II 1.",0TFMF    DB "TFMcom1.",0ETFO    DB "ETracker (C) BY ESI",0PSMFO   DB "psm1",0STPFO   DB "KSA SOFTWARE COMPILATION OF"        DB 0PSCFO   DB "PSC V1.0",0FTFO    DB "Module: ",0        DB "Fast Tracker v1.",0ASCFO   DB "ASM COMPILATION OF ",0GTFO    DB "GTR",0FXFO    DB "FXSM",0AYLH    DB "ZX Spectrum Sound Chip "        DB "Emulator Play List File "        DB "v1.",0;---------------------------------------MODES   DB " F2",5,5,#FE:DW MLOOP:DB 13        DB " F3",5,5,#FE:DW MSTEP:DB 13        DB " F4",5,5,#FE:DW MSTOP        NOPMLOOP   DB "   ",0Mloop   DB #0,3,2        DB "ALL"        DB "ONE"MSTEP   DB "       ",0Mstep   DB #0,7,3        DB "FORWARD"        DB "BCKWARD"        DB "SHUFFLE"MSTOP   DB "    ",0Mstop   DB #0,4,2        DB "PLAY"        DB "STOP";-------PLT0    DB 2," Editor:"        DB 7,7PL0     DB "                          "        DB 0PLT1    DB 2,"   Mode:"        DB 7,7,#FE:DW PL1        DB " track",0PL1     DB "   ",0CLOK    DB 0,0,0SLINE   DB 9PBLINE  DS 38,32        DB 10CLK     DB "00:00.00"MZNM    DS 32MZN2    DS 32GTPR    DS 64TXT1    DB 1,"   Name:",0TXT2    DB 1," Author:",0TXTSN1  DB #E,"Position: ","#"SN2     DB "00  Length: ","#"SN1     DB "00",0TME     DS 2TMM     DS 2SSTAT   NOPESTAT   NOPDETKA   DB 1P_ST    NOPTSFM    NOPTRIG    NOPGXMO    NOPSTA     NOPFMMZ    NOP;FM ModesSAAMZ   NOPTSMZ    NOP;TS ModeTSFG    NOPZZMZ    NOPVTMD    NOPFLAG    NOPPLMD    NOP ;Play List FlagHPMD    NOP ;Help Window FlagMUZPL   NOPPAUS    NOPONEB    DS 2TWOB    DS 2DAHL    DS 2DADE    DS 2DAIX    DS 2EXTNUM  NOPANWNDxy  DS 2;-Coordinates buffer 4 residentHLPWNDxy DS 2;/PLcount DS 2;Entrys in PLPLAYcur DS 2;Play cursorTFDFO   DB "TFMD",0HRFO    DB "hr2",0;-------DEHR21  INCB "DEHR21.COD"TESTnm  DB "test.pt3",0;-------LINENIN DB #E:DS 16,#C4:DB 0;-------SPR     DS 32*3END;---------------------------------------        ORG PLAYER1        INCB "PLAYERZ7.COD"        ORG PLAYER2        INCB "PLAYERS9.COD";---------------------------------------            ORG #8000,COD2;Residential areaSTARTCOD2;TEMP variables:TSMZres     NOPFMMZres     NOPSAAMZres    NOP;WC calls used from resident:MNGC_PLres  EXA:XOR A:JP WLDPRWOWres    LD A,1:JP WLDRRESBres    LD A,2:JP WLDPRSRWres    LD A,3:JP WLDTXTPRres    LD A,11:JP WLDMEZZres     EXA:LD A,12:JP WLDSPKEres     LD A,16:JP WLDENKEres     LD A,22:JP WLDESCres      LD A,23:JP WLD;Functions used from main:HLPWNDprwow LD (HLPWND+2),DE            LD IX,HLPWND:JP PRWOWresHLPWNDrresb LD IX,HLPWND:JP RRESBres;-----------ANWNDprwow  LD (ANWND+2),DE            LD IX,ANWND:JP PRWOWresANWNDrresb  LD IX,ANWND:JP RRESBresANALYZEanpr EXA:LD (TSMZres),A,(FMMZres),BC            CALL ANALYZE,ANPR            RET;-----------RND_INIres  LD A,R:OR 128:LD (SEEDrnd),A:RETRND_GENres  ;i:BC - MAX value;            o:BC - RND(0-MAX)            LD B,C            CALL RND:SUB B:JR NC,$-1:ADD A,B:LD C,A            LD B,0            RET;-----------LOAD_TSTres LD HL,TESTcod,DE,#C000,BC,TESTend-TESTcod            PUSH DE,BC:LDIR            POP BC,HL            LD DE,LOBU            RET;-----------WARNINGres  ;i:C - error message;            o:B - 0 - exit to commander;                  1 - go to next track anyway (time out/ENTER)            PUSH BC:LD IX,ERRWND:CALL PRWOWres            POP BC            LD A,C,HL,ERRORS,DE,#0101:CALL MEZZres            CALL WARNINGwTO            PUSH BC:CALL RRESBres            POP BC            RET;-----------LOADINGprwow LD IX,LOADWND:JP PRWOWresLOADINGrresb LD IX,LOADWND:JP RRESBres;---------------------------------------;FONT DECRUNCH;---------------------------------------FNTDECH;Pitch:        LD A,#FF:CALL MNGC_PLres        LD HL,#C000,DE,#C800,BC,8*20        LDIR        LD HL,#C000,DE,#C001,BC,8*20-1        LD (HL),L        LDIR        LD HL,#C000+8+7,DE,8        LD C,%01111110        LD A,1AFN     PUSH HL:LD B,A,(HL),C:DEC HL:DJNZ $-2        POP HL:ADD HL,DE        INC A:CP 9:JR C,AFN;Noize:        LD HL,#C000+8*NZ0CHAR,DE,%00000000 11111111        LD B,6NOIZEE  LD (HL),%11111111:INC L        LD A,B:SUB 6:JR Z,NZ1        LD C,A:XOR A:SUB C        LD C,B,B,A        LD (HL),E:INC L:DJNZ $-2        LD B,CNZ1     LD C,B        LD (HL),D:INC L:DJNZ $-2        LD B,C        LD (HL),%11111111:INC HL        DEC B:JR NZ,NOIZEE;Progressbar:        LD HL,PBRMK,DE,#C000+8*9,BC,8*3:LDIR        LD HL,DE,BC,0-8:ADD HL,BC        LD BC,8*8:LDIR        LD A,%10000000        LD B,8,HL,#C000+8*12+3,DE,8-1BUR     LD C,A:OR (HL):LD (HL),A:INC L        LD A,C:OR (HL):LD (HL),A        LD A,C        ADD HL,DE        SCF:RRA        DJNZ BUR        RET;---------------------------------------;AY/YM Analizer;---------------------------------------ANPR    LD IX,ANWND        LD HL,VZL1,DE,#0101,BC,40:CALL PRSRWres        LD HL,VZL2,DE,#0201,BC,40:CALL PRSRWres        LD HL,VZL3,DE,#0301,BC,40:JP PRSRWres;-------FRQSRL;Noize        LD HL,VZL3+4.32     LD A,(HL):CP NZ0CHAR:JR Z,$+3:DEC (HL):INC HL;Pitch        LD HL,VZL1,DE,VZL2,B,40JAJA    LD A,(HL):OR A:JR Z,AJA:DEC (HL)A_A     INC HL,DE:DJNZ JAJA        RETAJA     LD A,(DE):SUB 1:JR C,A_A:LD (DE),A        JP A_A;-------NOIZE   LD BC,#FFFD        LD A,7:OUT A:IN A:AND %00111000:XOR %00111000:RET Z;no noise        LD A,6:OUT A:IN A:AND %00011111        LD HL,VZL3+4,D,0,E,A:ADD HL,DE        LD (HL),NZHCHAR        RET;-------ANALYZE CALL FRQSRL        LD BC,(FMMZres)        LD A,B:OR A:RET NZ        LD A,C:OR A:JR NZ,FMman        LD A,(TSMZres):OR A:JR Z,LYZA        LD BC,#FFFD,A,#FE:OUT A:CALL LYZA        LD BC,#FFFD,A,#FF:OUT ALYZA    CALL NOIZE        LD DE,#108:CALL CHANL        LD DE,#309:CALL CHANL        LD DE,#50A:JP CHANL;-------KED     DS 3;-------FMman   LD A,15,BC,(KED):CALL KEDY        LD A,15,BC,(KED),HL,40-1:OR A:SBC HL,BC:LD BC,HL:CALL KEDY        LD A,(KED+2):OR A:JR NZ,KEDdec        LD HL,KED:INC (HL):LD A,(HL):CP 40:RET C        LD (HL),40-1,(KED+2),A        RETKEDdec  LD HL,KED,A,(HL):OR A:JR Z,$+4:DEC (HL):RET:LD (KED+2),A:RET;-------CHANL   LD BC,#FFFD        OUT D;REG Sel (Pitch Hi)        IN A:AND %00001111:LD H,A        DEC D:OUT D;REG Sel (Pitch Lo)        IN A:LD L,A        OUT E;REG Sel (Volume)        IN A:AND %00001111        LD BC,HL        EXA        LD HL,ANALYZR,A,40PYZDEK  LD E,(HL):INC HL        LD D,(HL):INC HL        EX DE,HL:SBC HL,BC        EX DE,HL:DEC A:JP C,PYZDEK        LD B,0,C,A        EXAKEDY    LD HL,VZL1:ADD HL,BC:LD C,40        CP 9:JR C,TYN        SUB 8:LD (HL),A        LD A,8TyN     ADD HL,BC:LD (HL),A        RETTYN     LD (HL),0        JR TyN;-------ANALYZR DW 12,15,18,21,25,30,35,42,50,59        DW 71,84,100,119,141,168,200,238,283,336        DW 400,476,565,672,800,951,1131,1345,1599,1902        DW 2262,2539,2690,2850,3019,3199,3389,3590,3803        DW 65535;40;---------------------------------------;RND generator;---------------------------------------SEEDrnd EQU RND+1RND     LD HL,#FFFF:ADD HL,HL:SBC A,A:AND #EB        LD C,A        XOR L:LD L,A,A,C:XOR H:LD H,A,(SEEDrnd),HL        AND %10101010:ADD A,L        RET;---------------------------------------;Module Error Time-OUT;---------------------------------------WARNINGwTO  LD BC,TimeOut,(TIME_OUT+1),BCWait        EI:HALT            CALL TIME_OUT:LD B,1:RET NC            CALL ESCres:LD B,0:RET NZ            CALL ENKEres:LD B,1:RET NZ            CALL SPKEres:LD B,1:RET NZ            JR WaitTIME_OUT LD BC,0:DEC BC:LD (TIME_OUT+1),BC         LD A,B:OR C:RET Z         LD HL,BC,DE,Frames         XOR A         LD A,"0"SUB      SBC HL,DE:INC A:JR NC,SUB         DEC A:LD (WAITSEC),A         LD HL,WAITING,DE,#0201:CALL TXTPRres         SCF         RET;---------------------------------------;Progress BAR chars:PBRMK   DB %00000000        DB %00000111        DB %00000110        DB %00000110        DB %00000110        DB %00000110        DB %00000111        DB %00000000        DB %00000000        DB %11100000        DB %01100000        DB %01100000        DB %01100000        DB %01100000        DB %11100000        DB %00000000        DB %00000000        DB %11111111        DB %00000000        DB %10101010        DB %01010101        DB %00000000        DB %11111111        DB %00000000;---------------------------------------ANWND   DB 4+16+128,0        DB ANX,ANY;    X,Y        DB ANW,ANH;    W,H        DB MDC;        PAPER+INK        DB 0        DW #0000;      BUFFER        DB 0,0;        LINES        DW ANTXT        DW 0        DW 0ANTXT   DB #0B,1,#9,"F1 - Help  M - Pause  SPACE - Next track",0;---------------------------------------HLPWND  DB 4+16,0        DB HLPX,HLPY;  X,Y        DB HLPW,HLPH;  W,H        DB HLPC;       PAPER+INK        DB 0        DW #0000;      BUFFER        DB 0,0;        LINES        DW HLPTOP        DW HLPBOT        DW HLPTXTHLPTOP  DB #E,#9,"Help",0HLPBOT  DB #B,1,#9,"F1 - Hide this Window",0HLPTXT  DB #E,"SPACE - play next file",13        DB #E,"ENTER - play file under cursor (play list mode)",13        DB #E,"UP/DOWN - select file (play list mode)",13        DB #E,"F2/F3/F4 - REPEAT type/ORDER mode/PLAYstop (play list mode)"        DB 0;---------------------------------------ERRWND  DB 4+16,0        DB 255,255;    X,Y        DB ERRW,ERRH;  W,H        DB ERRC;       PAPER+INK        DB 0        DW #0000;      BUFFER        DB 0,0;        LINES        DW ERRTOP        DW ERRBOT        DW 0ERRTOP  DB #E,#9,"Warning!",0ERRTXT  ;Error message        ;WAITINGERRBOT  DB #9,"Press ENTER to continue or ESC - to exit",0ERRORS  DB #E,"0",0,0;0        DB #E,"Unknown module!!!",0,0;1        DB #E,"TFC invalid!!!",0,0;2        DB #E,"TSFM detect failed!!!",0,0;3WAITING DB #E,"Starting next file in "WAITSEC DB "9"," seconds",0;---------------------------------------LOADWND DB 4+16,0        DB 255,255;    X,Y        DB LOADW,LOADH;W,H        DB LOADC;      PAPER+INK        DB 0        DW #0000;      BUFFER        DB 0,0;        LINES        DW LOADTOP        DW 0        DW LOADTXTLOADTOP DB #E,#9,"Loading!",0LOADTXT DB #E,"Please wait...",0;---------------------------------------VZL1    DS 40,8;- AY/YM AnalisatorVZL2    DS 40,8;/VZL3    DS 40,NZ0CHAR;Noize;---------------------------------------TESTcod INCB "test.pt3.cdb"TESTend;---------------------------------------ENDCOD2;---------------------------------------STLN    EQU 1084PT2LN   EQU 2459PT3LN   EQU #BE1PSCLN   EQU 2987FTLN    EQU 3077STPLN   EQU 1896GTLN    EQU 1690ASCLN   EQU 1458SQLN    EQU 1348;1296FMLN    EQU #73D;43VTLN    EQU #651FLSLN   EQU #5E6FXLN    EQU #511PT1LN   EQU #6C6ETLN    EQU 1203TFDLN   EQU #200PSMLN   EQU #494;-------MMODUL  EQU #C000+PT3PLPT2DL   EQU #C000+PT2PLSTPDL   EQU #C000+STPLNSTDL    EQU #C000+STLNPSCDL   EQU #C000+PSCLNFTDL    EQU #C000+FTLNGTDL    EQU #C000+GTLNASCDL   EQU #C000+ASCLNSQDL    EQU #C000+SQLNFMDL    EQU #C000+FMLNVTDL    EQU #C000+VTPLFLSDL   EQU #C000+FLSLNFXDL    EQU #C000+FXLNPT1DL   EQU #C000+PT1LNETDL    EQU #C000+ETLNTFDDL   EQU #C000+TFDLNPSMDL   EQU #C000+PSMLN;---------------------------------------